// Package ini parses INI configuration text.
package ini

import (
	"cmp"
	"fmt"
	"slices"
	"strconv"
	"strings"
	"time"
)

// File maps a section name to its keys and values. Keys before any header are in section "".
type File map[string]map[string]string

// Error is a syntax error at a 1-based line.
type Error struct {
	Line int
	Msg  string
}

func (e *Error) Error() string {
	return fmt.Sprintf("ini: line %d: %s", e.Line, e.Msg)
}

// Parse parses INI text.
func Parse(text string) (File, error) {
	raw := map[string]map[string]entry{}
	section := ""
	lines := strings.Split(text, "\n")
	for i := 0; i < len(lines); i++ {
		number := i + 1
		line := trim(lines[i])
		for strings.HasSuffix(line, `\`) {
			line = trim(strings.TrimSuffix(line, `\`))
			if i+1 < len(lines) {
				i++
				line += " " + trim(lines[i])
			}
		}
		fail := func(msg string) (File, error) { return nil, &Error{Line: number, Msg: msg} }
		switch {
		case line == "" || line[0] == ';' || line[0] == '#':
		case line[0] == '[':
			if !strings.HasSuffix(line, "]") {
				return fail("unclosed section header")
			}
			section = trim(line[1 : len(line)-1])
			if section == "" {
				return fail("empty section name")
			}
			if raw[section] == nil {
				raw[section] = map[string]entry{}
			}
		default:
			key, value, ok := strings.Cut(line, "=")
			if !ok {
				return fail("missing =")
			}
			if key = trim(key); key == "" {
				return fail("empty key")
			}
			value, msg := unquote(trim(value))
			if msg != "" {
				return fail(msg)
			}
			if raw[section] == nil {
				raw[section] = map[string]entry{}
			}
			raw[section][key] = entry{number, value}
		}
	}
	return interpolate(raw)
}

func trim(s string) string {
	return strings.Trim(s, " \t\r")
}

// unquote decodes a value wrapped in double quotes, or returns any other value unchanged.
func unquote(v string) (string, string) {
	if !strings.HasPrefix(v, `"`) {
		return v, ""
	}
	var b strings.Builder
	for i := 1; i < len(v); i++ {
		switch v[i] {
		case '"':
			if i != len(v)-1 {
				return "", "text after closing quote"
			}
			return b.String(), ""
		case '\\':
			if i++; i == len(v) || v[i] != '"' && v[i] != '\\' {
				return "", "invalid escape"
			}
		}
		b.WriteByte(v[i])
	}
	return "", "unterminated quote"
}

// entry is a parsed value before interpolation, with the line of its assignment.
type entry struct {
	line  int
	value string
}

type name struct{ section, key string }

// interpolate expands references in every value, failing at the first key in line order that cannot be expanded.
func interpolate(raw map[string]map[string]entry) (File, error) {
	file := File{}
	var order []name
	for section, keys := range raw {
		file[section] = map[string]string{}
		for key := range keys {
			order = append(order, name{section, key})
		}
	}
	slices.SortFunc(order, func(a, b name) int { return cmp.Compare(raw[a.section][a.key].line, raw[b.section][b.key].line) })
	visiting := map[name]bool{}
	var expand func(n name) bool
	expand = func(n name) bool {
		if _, done := file[n.section][n.key]; done {
			return true
		}
		e, ok := raw[n.section][n.key]
		if !ok || visiting[n] {
			return false
		}
		visiting[n] = true
		var b strings.Builder
		for s := e.value; s != ""; {
			i := strings.IndexByte(s, '$')
			if i < 0 || i == len(s)-1 {
				b.WriteString(s)
				break
			}
			b.WriteString(s[:i])
			switch s[i+1] {
			case '$':
				b.WriteByte('$')
				s = s[i+2:]
			case '{':
				end := strings.IndexByte(s[i:], '}')
				if end < 0 {
					return false
				}
				ref := name{n.section, s[i+2 : i+end]}
				if section, key, ok := strings.Cut(ref.key, ":"); ok {
					ref = name{section, key}
				}
				if !expand(ref) {
					return false
				}
				b.WriteString(file[ref.section][ref.key])
				s = s[i+end+1:]
			default:
				b.WriteByte('$')
				s = s[i+1:]
			}
		}
		file[n.section][n.key] = b.String()
		return true
	}
	for _, n := range order {
		if !expand(n) {
			return nil, &Error{Line: raw[n.section][n.key].line, Msg: fmt.Sprintf("cannot interpolate %s", n.key)}
		}
	}
	return file, nil
}

// Get returns the value of key in section and whether it exists.
func (f File) Get(section, key string) (string, bool) {
	v, ok := f[section][key]
	return v, ok
}

// Bool parses the value of key in section as a boolean.
func (f File) Bool(section, key string) (bool, error) {
	v, err := f.value(section, key)
	if err != nil {
		return false, err
	}
	switch strings.ToLower(v) {
	case "1", "true", "yes", "on":
		return true, nil
	case "0", "false", "no", "off":
		return false, nil
	}
	return false, fmt.Errorf("ini: [%s] %s: %q is not a boolean", section, key, v)
}

// Int parses the value of key in section as an integer.
func (f File) Int(section, key string) (int64, error) {
	v, err := f.value(section, key)
	if err != nil {
		return 0, err
	}
	return strconv.ParseInt(v, 0, 64)
}

// Duration parses the value of key in section as a duration.
func (f File) Duration(section, key string) (time.Duration, error) {
	v, err := f.value(section, key)
	if err != nil {
		return 0, err
	}
	return time.ParseDuration(v)
}

func (f File) value(section, key string) (string, error) {
	v, ok := f.Get(section, key)
	if !ok {
		return "", fmt.Errorf("ini: [%s] %s is missing", section, key)
	}
	return v, nil
}

