// Package ratelimit is a token-bucket rate limiter driven by an injected clock.
package ratelimit

import (
	"math"
	"time"
)

// Clock supplies the current time.
type Clock interface {
	Now() time.Time
}

// Limiter is a token bucket.
type Limiter struct {
	clock  Clock
	rate   float64
	burst  float64
	tokens float64
	last   time.Time
}

// New returns a limiter refilling rate tokens per second up to burst tokens.
func New(rate float64, burst int, clock Clock) *Limiter {
	size := float64(max(burst, 0))
	return &Limiter{clock: clock, rate: rate, burst: size, tokens: size, last: clock.Now()}
}

// refill adds the tokens earned since the last observation. A clock going back earns nothing.
func (l *Limiter) refill() {
	now := l.clock.Now()
	if !now.After(l.last) {
		return
	}
	if l.rate > 0 {
		l.tokens = min(l.burst, l.tokens+now.Sub(l.last).Seconds()*l.rate)
	}
	l.last = now
}

// Allow is AllowN(1).
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// AllowN takes n tokens if they are available.
func (l *Limiter) AllowN(n int) bool {
	l.refill()
	if n < 0 || n > 0 && float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Tokens reports the available tokens.
func (l *Limiter) Tokens() float64 {
	l.refill()
	return l.tokens
}

// Delay reports how long until AllowN(n) can succeed.
func (l *Limiter) Delay(n int) time.Duration {
	l.refill()
	return l.delay(n)
}

// delay is how long until n tokens are held, rounded up to a nanosecond; -1 if never.
func (l *Limiter) delay(n int) time.Duration {
	need := float64(n) - l.tokens
	switch {
	case n < 0 || float64(n) > l.burst:
		return -1
	case n == 0 || need <= 0:
		return 0
	case l.rate <= 0:
		return -1
	}
	return time.Duration(math.Ceil(need / l.rate * float64(time.Second)))
}

// SetRate changes the refill rate.
func (l *Limiter) SetRate(rate float64) {
	l.refill()
	l.rate = rate
}

// SetBurst changes the bucket size.
func (l *Limiter) SetBurst(burst int) {
	l.refill()
	l.burst = float64(max(burst, 0))
	l.tokens = min(l.tokens, l.burst)
}

// Reservation is a claim on tokens that may not have been earned yet.
type Reservation struct {
	limiter   *Limiter
	n         int
	ready     time.Time
	ok        bool
	cancelled bool
}

// Reserve takes n tokens now, borrowing from future refills if needed.
func (l *Limiter) Reserve(n int) *Reservation {
	l.refill()
	wait := l.delay(n)
	if wait < 0 {
		return &Reservation{}
	}
	l.tokens -= float64(n)
	return &Reservation{limiter: l, n: n, ready: l.clock.Now().Add(wait), ok: true}
}

// OK reports whether the reservation was granted.
func (r *Reservation) OK() bool {
	return r.ok
}

// Delay reports how long until the reserved tokens are earned.
func (r *Reservation) Delay() time.Duration {
	if !r.ok {
		return -1
	}
	return max(0, r.ready.Sub(r.limiter.clock.Now()))
}

// Cancel returns the reserved tokens.
func (r *Reservation) Cancel() {
	if !r.ok || r.cancelled || r.limiter.clock.Now().After(r.ready) {
		return
	}
	r.cancelled = true
	l := r.limiter
	l.refill()
	l.tokens = min(l.burst, l.tokens+float64(r.n))
}

// Group keeps one limiter per key.
type Group struct {
	rate     float64
	burst    int
	clock    Clock
	limiters map[string]*Limiter
}

// NewGroup returns a group whose limiters share rate, burst and clock.
func NewGroup(rate float64, burst int, clock Clock) *Group {
	return &Group{rate: rate, burst: burst, clock: clock, limiters: map[string]*Limiter{}}
}

// Allow is AllowN(key, 1).
func (g *Group) Allow(key string) bool {
	return g.AllowN(key, 1)
}

// AllowN is AllowN(n) on key's limiter.
func (g *Group) AllowN(key string, n int) bool {
	return g.limiter(key).AllowN(n)
}

// Reserve is Reserve(n) on key's limiter.
func (g *Group) Reserve(key string, n int) *Reservation {
	return g.limiter(key).Reserve(n)
}

// Tokens reports key's available tokens.
func (g *Group) Tokens(key string) float64 {
	if l, ok := g.limiters[key]; ok {
		return l.Tokens()
	}
	return float64(max(g.burst, 0))
}

func (g *Group) limiter(key string) *Limiter {
	l, ok := g.limiters[key]
	if !ok {
		l = New(g.rate, g.burst, g.clock)
		g.limiters[key] = l
	}
	return l
}

// Len reports how many keys have a limiter.
func (g *Group) Len() int {
	return len(g.limiters)
}

// Prune removes the limiters that are full and reports how many it removed.
func (g *Group) Prune() int {
	removed := 0
	for key, l := range g.limiters {
		if l.Tokens() >= l.burst {
			delete(g.limiters, key)
			removed++
		}
	}
	return removed
}

// SetRate changes the rate of every limiter in the group.
func (g *Group) SetRate(rate float64) {
	g.rate = rate
	for _, l := range g.limiters {
		l.SetRate(rate)
	}
}

// SetBurst changes the burst of every limiter in the group.
func (g *Group) SetBurst(burst int) {
	g.burst = burst
	for _, l := range g.limiters {
		l.SetBurst(burst)
	}
}

