func checkConstraint(t *testing.T, constraint string, in, out []string) {
	t.Helper()
	c := mustConstraint(t, constraint)
	for _, s := range in {
		if !c.Check(mustSemver(t, s)) {
			t.Errorf("%q should accept %s", constraint, s)
		}
	}
	for _, s := range out {
		if c.Check(mustSemver(t, s)) {
			t.Errorf("%q should reject %s", constraint, s)
		}
	}
