func TestINIInterpolationErrors(t *testing.T) {
	cases := []struct {
		text string
		line int
	}{
		{"[s]\nok = 1\nbad = ${missing}\n", 3},
		{"[s]\nbad = ${nosuch:ok}\nok = 1\n", 2},
		{"[s]\nok = 1\nbad = x${ok\n", 3},
		{"[s]\nok = 1\na = ${b}\nb = ${a}\n", 3},
		{"[s]\nself = ${self}\n", 2},
		{"[s]\nfirst = ${second}\nsecond = ${gone}\n", 2},
		{"[s]\nx = 1\n[t]\ny = ${x}\n", 4},
	}
	for _, c := range cases {
		_, err := ini.Parse(c.text)
		var e *ini.Error
		if !errors.As(err, &e) {
			t.Errorf("Parse(%q) error = %v, want *ini.Error", c.text, err)
		} else if e.Line != c.line {
			t.Errorf("Parse(%q) line = %d, want %d", c.text, e.Line, c.line)
		}
	}
}

func TestINIGetters(t *testing.T) {
	f := mustINI(t, "debug = YES\n[n]\nhex = 0x1f\nneg = -7\nbig = 1_000\nwait = 1h30m\nshort = 250ms\noff = Off\none = 1\n")
	if v, ok := f.Get("n", "neg"); !ok || v != "-7" {
		t.Errorf("Get = %q, %v", v, ok)
	}
	if _, ok := f.Get("n", "nope"); ok {
		t.Error("Get found a missing key")
	}
	if _, ok := f.Get("nosuch", "hex"); ok {
		t.Error("Get found a key in a missing section")
	}
	for _, c := range []struct {
		section, key string
		want         bool
	}{{"", "debug", true}, {"n", "off", false}, {"n", "one", true}} {
		if got, err := f.Bool(c.section, c.key); err != nil || got != c.want {
			t.Errorf("Bool(%s, %s) = %v, %v", c.section, c.key, got, err)
		}
	}
	for key, want := range map[string]int64{"hex": 31, "neg": -7, "big": 1000, "one": 1} {
		if got, err := f.Int("n", key); err != nil || got != want {
			t.Errorf("Int(%s) = %v, %v", key, got, err)
		}
	}
	for key, want := range map[string]time.Duration{"wait": 90 * time.Minute, "short": 250 * time.Millisecond} {
		if got, err := f.Duration("n", key); err != nil || got != want {
			t.Errorf("Duration(%s) = %v, %v", key, got, err)
		}
	}
}

func TestINIGetterErrors(t *testing.T) {
	f := mustINI(t, "[e]\nword = maybe\ntwo = 2\nblank =\nbig = 9223372036854775808\nmixed = 12abc\nbare = 5\n")
	for _, key := range []string{"word", "two", "blank", "missing"} {
		if _, err := f.Bool("e", key); err == nil {
			t.Errorf("Bool(%s) accepted", key)
		}
	}
	for _, key := range []string{"word", "blank", "big", "mixed", "missing"} {
		if _, err := f.Int("e", key); err == nil {
			t.Errorf("Int(%s) accepted", key)
		}
	}
	for _, key := range []string{"word", "bare", "blank", "missing"} {
		if _, err := f.Duration("e", key); err == nil {
			t.Errorf("Duration(%s) accepted", key)
		}
	}
	if _, err := f.Int("nosuch", "two"); err == nil {
		t.Error("Int in a missing section accepted")
	}
}

