type fakeClock struct{ now time.Time }

func (c *fakeClock) Now() time.Time          { return c.now }
func (c *fakeClock) Advance(d time.Duration) { c.now = c.now.Add(d) }

func newLimiter(rate float64, burst int) (*ratelimit.Limiter, *fakeClock) {
	clock := &fakeClock{now: time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC)}
	return ratelimit.New(rate, burst, clock), clock
}

func wantTokens(t *testing.T, l *ratelimit.Limiter, want float64) {
	t.Helper()
	if got := l.Tokens(); math.Abs(got-want) > 1e-9 {
		t.Fatalf("Tokens() = %v, want %v", got, want)
	}
}

func drain(t *testing.T, l *ratelimit.Limiter, n int) {
	t.Helper()
	if !l.AllowN(n) {
		t.Fatalf("AllowN(%d) refused while draining", n)
	}
}

func TestLimiterStartsFull(t *testing.T) {
	l, _ := newLimiter(1, 3)
	wantTokens(t, l, 3)
	for i := 0; i < 3; i++ {
		if !l.Allow() {
			t.Fatalf("Allow %d refused", i)
		}
	}
	if l.Allow() {
		t.Fatal("fourth Allow accepted")
	}
}

func TestLimiterRefillsFractionally(t *testing.T) {
	l, clock := newLimiter(2, 4)
	drain(t, l, 4)
	clock.Advance(500 * time.Millisecond)
	wantTokens(t, l, 1)
	slow, slowClock := newLimiter(0.5, 2)
	drain(t, slow, 2)
	slowClock.Advance(time.Second)
	wantTokens(t, slow, 0.5)
	if slow.Allow() {
		t.Fatal("Allow accepted half a token")
	}
	slowClock.Advance(time.Second)
	if !slow.Allow() {
		t.Fatal("Allow refused a whole token")
	}
	wantTokens(t, slow, 0)
}

func TestLimiterSmallStepsAccumulate(t *testing.T) {
	l, clock := newLimiter(1, 1)
	drain(t, l, 1)
	for i := 0; i < 4; i++ {
		clock.Advance(250 * time.Millisecond)
		l.Tokens()
	}
	if !l.Allow() {
		t.Fatal("four quarter-second steps did not refill one token")
	}
}

func TestLimiterCapsAtBurst(t *testing.T) {
	l, clock := newLimiter(10, 5)
	drain(t, l, 2)
	clock.Advance(time.Hour)
	wantTokens(t, l, 5)
	if l.AllowN(6) || !l.AllowN(5) {
		t.Fatal("bucket not capped at burst")
	}
}

func TestLimiterAllowNIsAllOrNothing(t *testing.T) {
	l, _ := newLimiter(1, 5)
	drain(t, l, 3)
	if l.AllowN(3) {
		t.Fatal("AllowN(3) accepted with 2 tokens")
	}
	wantTokens(t, l, 2)
	drain(t, l, 2)
	if !l.AllowN(0) {
		t.Fatal("AllowN(0) refused on an empty bucket")
	}
	full, _ := newLimiter(1, 5)
	if full.AllowN(-1) || full.AllowN(6) {
		t.Fatal("negative or over-burst AllowN accepted")
	}
	wantTokens(t, full, 5)
}

func TestLimiterIgnoresClockGoingBack(t *testing.T) {
	l, clock := newLimiter(2, 10)
	drain(t, l, 10)
	clock.Advance(-time.Second)
	wantTokens(t, l, 0)
	clock.Advance(1500 * time.Millisecond)
	wantTokens(t, l, 1)
}

func TestLimiterWithoutRefillOrBurst(t *testing.T) {
	for _, rate := range []float64{0, -1} {
		l, clock := newLimiter(rate, 2)
		drain(t, l, 2)
		clock.Advance(time.Hour)
		if l.Allow() {
			t.Fatalf("rate %v refilled", rate)
		}
	}
	for _, burst := range []int{0, -3} {
		l, clock := newLimiter(5, burst)
		clock.Advance(time.Minute)
		if l.Allow() || !l.AllowN(0) {
			t.Fatalf("burst %d: wrong result", burst)
		}
		wantTokens(t, l, 0)
	}
}

func TestLimiterDelay(t *testing.T) {
	l, _ := newLimiter(2, 4)
	if d := l.Delay(4); d != 0 {
		t.Fatalf("Delay on full bucket = %v", d)
	}
	drain(t, l, 4)
	if d := l.Delay(1); d != 500*time.Millisecond {
		t.Fatalf("Delay(1) = %v", d)
	}
	if d := l.Delay(0); d != 0 {
		t.Fatalf("Delay(0) = %v", d)
	}
	if l.Delay(-1) != -1 || l.Delay(5) != -1 {
		t.Fatal("impossible Delay not -1")
	}
	wantTokens(t, l, 0)
	third, thirdClock := newLimiter(3, 1)
	drain(t, third, 1)
	d := third.Delay(1)
	if d != 333333334*time.Nanosecond {
		t.Fatalf("Delay rounds %v, want up to 333.333334ms", d)
	}
	thirdClock.Advance(d)
	if !third.Allow() {
		t.Fatal("Allow refused after waiting Delay")
	}
	stopped, _ := newLimiter(0, 2)
	drain(t, stopped, 2)
	if stopped.Delay(1) != -1 || stopped.Delay(0) != 0 {
		t.Fatal("rate 0 Delay wrong")
	}
}

func TestLimiterSetRate(t *testing.T) {
	l, clock := newLimiter(1, 10)
	drain(t, l, 10)
	clock.Advance(2 * time.Second)
	l.SetRate(4)
	wantTokens(t, l, 2)
	clock.Advance(500 * time.Millisecond)
	wantTokens(t, l, 4)
	l.SetRate(0)
	clock.Advance(time.Hour)
	wantTokens(t, l, 4)
}

func TestLimiterSetBurst(t *testing.T) {
	l, clock := newLimiter(1, 10)
	drain(t, l, 4)
	l.SetBurst(3)
	wantTokens(t, l, 3)
	l.SetBurst(8)
	wantTokens(t, l, 3)
	clock.Advance(time.Hour)
	wantTokens(t, l, 8)
	if l.AllowN(9) || !l.AllowN(8) {
		t.Fatal("new burst not applied")
	}
	l.SetBurst(-2)
	clock.Advance(time.Hour)
	wantTokens(t, l, 0)
}

func TestReserveWithinTokens(t *testing.T) {
	l, _ := newLimiter(1, 5)
	r := l.Reserve(3)
	if !r.OK() || r.Delay() != 0 {
		t.Fatalf("Reserve(3) on full bucket: OK %v, Delay %v", r.OK(), r.Delay())
	}
	wantTokens(t, l, 2)
}

func TestReserveBorrows(t *testing.T) {
	l, clock := newLimiter(2, 4)
	drain(t, l, 4)
	r := l.Reserve(3)
	if !r.OK() || r.Delay() != 1500*time.Millisecond {
		t.Fatalf("Reserve(3): OK %v, Delay %v", r.OK(), r.Delay())
	}
	wantTokens(t, l, -3)
	if l.Allow() || !l.AllowN(0) {
		t.Fatal("Allow with debt")
	}
	if d := l.Delay(1); d != 2*time.Second {
		t.Fatalf("Delay(1) with debt = %v", d)
	}
	if d := l.Delay(0); d != 0 {
		t.Fatalf("Delay(0) with debt = %v", d)
	}
	if zero := l.Reserve(0); !zero.OK() || zero.Delay() != 0 {
		t.Fatalf("Reserve(0) with debt: OK %v, Delay %v", zero.OK(), zero.Delay())
	}
	clock.Advance(time.Second)
	if r.Delay() != 500*time.Millisecond {
		t.Fatalf("Delay after 1s = %v", r.Delay())
	}
	wantTokens(t, l, -1)
	clock.Advance(time.Second)
	if r.Delay() != 0 {
		t.Fatalf("Delay after ready = %v", r.Delay())
	}
	wantTokens(t, l, 1)
}

func TestReserveRefused(t *testing.T) {
	l, _ := newLimiter(1, 4)
	for _, n := range []int{-1, 5} {
		if r := l.Reserve(n); r.OK() || r.Delay() != -1 {
			t.Fatalf("Reserve(%d): OK %v, Delay %v", n, r.OK(), r.Delay())
		}
	}
	wantTokens(t, l, 4)
	stopped, _ := newLimiter(0, 4)
	drain(t, stopped, 3)
	if r := stopped.Reserve(2); r.OK() || r.Delay() != -1 {
		t.Fatal("Reserve beyond tokens without refill granted")
	}
	if r := stopped.Reserve(1); !r.OK() || r.Delay() != 0 {
		t.Fatal("Reserve within tokens without refill refused")
	}
	wantTokens(t, stopped, 0)
}

func TestReservationCancel(t *testing.T) {
	l, clock := newLimiter(2, 4)
	drain(t, l, 4)
	r := l.Reserve(2)
	clock.Advance(500 * time.Millisecond)
	r.Cancel()
	wantTokens(t, l, 1)
	r.Cancel()
	wantTokens(t, l, 1)
	late := l.Reserve(3)
	clock.Advance(2 * time.Second)
	late.Cancel()
	wantTokens(t, l, 2)
	refused := l.Reserve(9)
	refused.Cancel()
	wantTokens(t, l, 2)
}

func TestReservationCancelCapsAtBurst(t *testing.T) {
	l, _ := newLimiter(1, 4)
	r := l.Reserve(1)
	l.SetBurst(2)
	r.Cancel()
	wantTokens(t, l, 2)
}

func TestGroupKeysAreIndependent(t *testing.T) {
	g := ratelimit.NewGroup(1, 2, &fakeClock{now: time.Unix(0, 0)})
	if !g.Allow("a") || !g.Allow("a") || g.Allow("a") {
		t.Fatal("key a not limited at burst 2")
	}
	if !g.AllowN("b", 2) || g.Allow("b") {
		t.Fatal("key b not independent")
	}
	if !g.AllowN("c", 0) || g.Len() != 3 {
		t.Fatalf("Len = %d, want 3", g.Len())
	}
}

func TestGroupPrune(t *testing.T) {
	clock := &fakeClock{now: time.Unix(0, 0)}
	g := ratelimit.NewGroup(1, 2, clock)
	g.AllowN("a", 2)
	g.AllowN("b", 1)
	g.AllowN("idle", 0)
	clock.Advance(time.Second)
	if n := g.Prune(); n != 2 || g.Len() != 1 {
		t.Fatalf("Prune = %d, Len = %d; want 2, 1", n, g.Len())
	}
	if !g.Allow("a") || g.Allow("a") {
		t.Fatal("pruning reset a remaining limiter")
	}
	if !g.AllowN("b", 2) || g.Len() != 2 {
		t.Fatal("pruned key did not come back full")
	}
	stopped := ratelimit.NewGroup(0, 1, clock)
	stopped.Allow("x")
	clock.Advance(time.Hour)
	if stopped.Prune() != 0 || stopped.Len() != 1 {
		t.Fatal("pruned a limiter that cannot refill")
	}
}

func TestGroupReserveAndTokens(t *testing.T) {
	clock := &fakeClock{now: time.Unix(0, 0)}
	g := ratelimit.NewGroup(2, 3, clock)
	if got := g.Tokens("new"); got != 3 || g.Len() != 0 {
		t.Fatalf("Tokens of an unseen key = %v, Len %d", got, g.Len())
	}
	r := g.Reserve("k", 3)
	if !r.OK() || r.Delay() != 0 || g.Len() != 1 {
		t.Fatal("Reserve on a new key")
	}
	if r := g.Reserve("k", 1); !r.OK() || r.Delay() != 500*time.Millisecond {
		t.Fatalf("Reserve into debt: OK %v, Delay %v", r.OK(), r.Delay())
	}
	if got := g.Tokens("k"); math.Abs(got+1) > 1e-9 {
		t.Fatalf("Tokens(k) = %v, want -1", got)
	}
	if g.Reserve("other", 4).OK() {
		t.Fatal("Reserve over burst granted")
	}
}

func TestGroupSetRateAndBurst(t *testing.T) {
	clock := &fakeClock{now: time.Unix(0, 0)}
	g := ratelimit.NewGroup(1, 4, clock)
	g.AllowN("a", 4)
	clock.Advance(time.Second)
	g.SetRate(3)
	if got := g.Tokens("a"); math.Abs(got-1) > 1e-9 {
		t.Fatalf("Tokens(a) after SetRate = %v, want 1", got)
	}
	clock.Advance(500 * time.Millisecond)
	if got := g.Tokens("a"); math.Abs(got-2.5) > 1e-9 {
		t.Fatalf("Tokens(a) at new rate = %v, want 2.5", got)
	}
	g.SetBurst(2)
	if got := g.Tokens("a"); math.Abs(got-2) > 1e-9 {
		t.Fatalf("Tokens(a) after SetBurst = %v, want 2", got)
	}
	if got := g.Tokens("fresh"); got != 2 {
		t.Fatalf("Tokens of an unseen key after SetBurst = %v", got)
	}
	g.AllowN("b", 2)
	clock.Advance(500 * time.Millisecond)
	if got := g.Tokens("b"); math.Abs(got-1.5) > 1e-9 || g.AllowN("b", 3) {
		t.Fatalf("new key ignores group settings: Tokens %v", got)
	}
}
